@extends('admin.layout') @section('title','Submissions') @section('heading','Submission Review') @push('styles')<style>.row{display:grid;grid-template-columns:2fr 1fr 1fr;gap:12px;align-items:center}.item{margin-bottom:13px}.meta{font-size:12px;color:#667085;margin-top:4px}.actions{display:grid;grid-template-columns:1fr auto auto;gap:8px;margin-top:15px}.status{display:inline-flex;padding:5px 9px;border-radius:99px;background:#eef1ff;color:#4459c5;font-size:11px;font-weight:850}.danger{background:#f04438}@media(max-width:650px){.row,.actions{grid-template-columns:1fr}}</style>@endpush @section('content')@forelse($submissions as $s)<section class="card item"><div class="row"><div><strong>{{ $s->workerTask->task->title }}</strong><div class="meta">{{ $s->workerTask->user->name }} · {{ $s->workerTask->user->email }}</div><div class="meta">{{ $s->original_name }} · {{ number_format(($s->file_size ?? 0)/1024,1) }} KB</div></div><span class="status">{{ ucfirst($s->status) }}</span><strong>${{ number_format((float)$s->workerTask->task->reward,2) }}</strong></div>@if($s->status==='pending')<form class="actions" method="POST" action="{{ route('admin.submissions.review',$s) }}">@csrf @method('PATCH')<input class="input" name="verification_notes" placeholder="Verification notes (optional)"><button class="btn" name="status" value="approved">Approve</button><button class="btn danger" name="status" value="rejected">Reject</button></form>@else<p class="meta">Review note: {{ $s->verification_notes ?: 'No note' }}</p>@endif</section>@empty<section class="card"><p class="muted">No submissions yet.</p></section>@endforelse<div>{{ $submissions->links() }}</div>@endsection